<script setup lang="ts">
import type {ProductDetail,TutorialDetail} from '@devstore/shared-types';import {money} from '@devstore/ui/format';import {BookOpen,ArrowRight,ShieldCheck,LockKeyhole,Check} from '@lucide/vue';
const route=useRoute();const api=useApi();const {buy,pending:buying,error:buyError}=usePurchase();
const {data:product,error,status,refresh}=await useAsyncData(()=> 'product:'+route.params.slug,()=>api.request<ProductDetail>('/products/'+encodeURIComponent(String(route.params.slug))));
const {data:tutorial}=await useAsyncData(()=> 'product-chapters:'+route.params.slug,()=>product.value?.tutorial_slug?api.request<TutorialDetail>('/tutorials/'+encodeURIComponent(product.value.tutorial_slug)):Promise.resolve(null));
useSeoMeta({title:()=>product.value?product.value.title+' · DevStore':'教程详情 · DevStore',description:()=>product.value?.description||'探索项目实战教程'});
</script>
<template><div class="container"><div class="page-head"><div class="breadcrumbs"><NuxtLink to="/">首页</NuxtLink><span>/</span><NuxtLink to="/products">商品商城</NuxtLink><span>/ 教程详情</span></div><ApiFeedback :pending="status==='pending'" :error="error" @retry="refresh"/><template v-if="product"><div class="row"><span class="badge purple"><BookOpen :size="12"/> 项目实战教程</span><span v-if="product.is_demo" class="badge amber">示例内容</span></div><h1 style="max-width:800px">{{ product.title }}</h1><p class="muted">{{ product.description }}</p></template></div>
<div v-if="product" class="detail-grid"><div class="stack"><section class="panel"><div class="eyebrow" style="margin-bottom:14px">BUILD SOMETHING REAL</div><h2 style="font-size:23px">理解原理，更能独立构建。</h2><p class="muted">{{ product.description }}</p><p class="muted" style="font-size:14px">按章节循序渐进地学习。你可以先阅读免费预览，确认内容适合自己，再选择购买。</p><div class="row" style="margin-top:25px;color:#a5b9cc;font-size:12px"><Check :size="16" style="color:var(--green)"/> 图文讲解与代码示例</div></section><section v-if="tutorial" class="panel"><div class="spread" style="margin-bottom:18px"><h2 style="font-size:20px;margin:0">教程目录</h2><span class="muted" style="font-size:12px">{{ tutorial.chapters.length }} 个章节</span></div><ul class="chapter-list"><li v-for="chapter in tutorial.chapters" :key="chapter.id"><NuxtLink :to="{path:'/tutorials/'+tutorial.slug,query:{chapter:chapter.id}}"><span class="row"><BookOpen v-if="chapter.is_preview" :size="16"/><LockKeyhole v-else :size="16"/>{{ chapter.title }}</span><span class="badge" :class="{green:chapter.is_preview}">{{ chapter.is_preview?'免费预览':'购买解锁' }}</span></NuxtLink></li></ul></section></div>
<aside class="purchase-panel panel"><span class="muted" style="font-size:13px">教程完整访问</span><div class="price">{{ product.price_cents===0?'免费领取':money(product.price_cents) }}</div><p class="muted" style="font-size:12px">一次购买 · 账号内阅读。未配置收款信息时不能购买。</p><button class="btn" :disabled="buying" @click="buy(product.id)">{{ buying?'正在创建订单…':product.price_cents===0?'领取教程':'购买教程' }}<ArrowRight :size="16"/></button><p v-if="buyError" role="alert" class="error">{{ buyError }}</p><NuxtLink v-if="tutorial" class="btn secondary" :to="'/tutorials/'+tutorial.slug">先看免费预览</NuxtLink><div class="divider"/><ul><li>人工核实到账后开通阅读</li><li>可在「我的订单」查看进度</li><li>已购内容在「我的资源」中查看</li></ul><div class="row muted" style="font-size:11px"><ShieldCheck :size="16"/> 付款与开通记录可查询</div></aside></div></div></template>
